BEGIN;
DO $cleanup$ BEGIN
IF (select count(*) from auth.users where id in ('a144b6eb-97e8-43a9-a7c5-bc8b8cba8ffe'::uuid,'224a41e3-ceff-468d-87d7-e908dc128c38'::uuid,'891d86fc-fcad-4358-a356-359849b2324f'::uuid,'f9b15895-c307-40e7-8701-cccf9066b36f'::uuid,'9a9e1dfd-2a25-4309-8287-fa457eb9e6c2'::uuid) and email ~ '^social-(owner|friend|friend2|friend3|admin|a|b)-1793075388485@test[.]local$') <> 5 THEN RAISE EXCEPTION 'fixture_auth_scope_changed'; END IF;
IF EXISTS(select 1 from public.goal where member_id in ('a144b6eb-97e8-43a9-a7c5-bc8b8cba8ffe'::uuid,'224a41e3-ceff-468d-87d7-e908dc128c38'::uuid,'891d86fc-fcad-4358-a356-359849b2324f'::uuid,'f9b15895-c307-40e7-8701-cccf9066b36f'::uuid,'9a9e1dfd-2a25-4309-8287-fa457eb9e6c2'::uuid) and id not in (505,506,503,498,499,500,501,502,504)) OR EXISTS(select 1 from public.goal where id in (505,506,503,498,499,500,501,502,504) and member_id not in ('a144b6eb-97e8-43a9-a7c5-bc8b8cba8ffe'::uuid,'224a41e3-ceff-468d-87d7-e908dc128c38'::uuid,'891d86fc-fcad-4358-a356-359849b2324f'::uuid,'f9b15895-c307-40e7-8701-cccf9066b36f'::uuid,'9a9e1dfd-2a25-4309-8287-fa457eb9e6c2'::uuid)) THEN RAISE EXCEPTION 'fixture_goal_scope_changed'; END IF;
IF EXISTS(select 1 from public.payment where id in (1585,1586,1587,1588,1589,1590,1591,1592,1593,1594,1595,1596,1597,1598,1599,1600,1601,1602,1603,1604,1605,1606,1607,1608,1609,1610,1611,1612,1613,1614,1615) and order_id not like 'social-1793075388485-%') THEN RAISE EXCEPTION 'fixture_payment_scope_changed'; END IF;
IF EXISTS(select 1 from public.cheer c join public.goal g on g.id=c.goal_id where c.goal_id in (505,506,503,498,499,500,501,502,504) and (c.payment_id not in (1585,1586,1587,1588,1589,1590,1591,1592,1593,1594,1595,1596,1597,1598,1599,1600,1601,1602,1603,1604,1605,1606,1607,1608,1609,1610,1611,1612,1613,1614,1615) or (c.payment_id is null and c.created_at is distinct from g.created_at))) THEN RAISE EXCEPTION 'fixture_cheer_scope_changed'; END IF;
