DELETE FROM public.cheer WHERE goal_id in (505,506,503,498,499,500,501,502,504);
DELETE FROM public.admin_member WHERE member_id in ('a144b6eb-97e8-43a9-a7c5-bc8b8cba8ffe'::uuid,'224a41e3-ceff-468d-87d7-e908dc128c38'::uuid,'891d86fc-fcad-4358-a356-359849b2324f'::uuid,'f9b15895-c307-40e7-8701-cccf9066b36f'::uuid,'9a9e1dfd-2a25-4309-8287-fa457eb9e6c2'::uuid);
